function validateBinding(binding: WorkContextBinding, now: Clock): WorkContextBinding {
  try {
    return assertActiveWorkContextBinding(binding, now);
  } catch (error) {
    throw new ToolResultError("TOOL_RESULT_UNAUTHORIZED", "An active trusted Work Context binding is required", {
      cause: error,
    });
  }
}

type WorkContextBinding = {
  version: 1;
  id: string;
  status: "active" | "superseded";
  host: string;
  session_id: string;
  bound_at: string;
  last_seen_at: string;
  expires_at: string;
  collaboration_space: WorkspaceRef;
  provenance: {
    kind: "host_lifecycle" | "operator_rebind";
    lifecycle: string;
    observed_cwd: string;
  };
  superseded_by?: string;
  superseded_at?: string;
};

function workContextBindingView(binding: WorkContextBinding): WorkContextBindingView {
  const { session_id: _sessionId, provenance, ...publicBinding } = binding;
  return {
    ...publicBinding,
    provenance: {
      kind: provenance.kind,
      lifecycle: provenance.lifecycle,
    },
  };
}

class WorkContextError extends Error {
  readonly code: WorkContextErrorCode;

  constructor(code: WorkContextErrorCode, message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "WorkContextError";
    this.code = code;
  }
}

type CaptureCommandResultOptions = {
  argv: string[];
  producer: string;
  binding: WorkContextBinding;
  stateRoot?: string;
  cwd?: string;
  now?: Clock;
};

async function captureCommandResult(options: CaptureCommandResultOptions): Promise<ToolResultReceipt> {
  const clock = options.now ?? nowIso;
  const binding = validateBinding(options.binding, clock);
  const producer = validateProducer(options.producer);
  const createdAt = clock();
  const createdAtMs = Date.parse(createdAt);
  if (!Number.isFinite(createdAtMs)) {
    throw new ToolResultError("TOOL_RESULT_INVALID_REQUEST", "now must return an ISO date-time");
  }
  const expiresAt = new Date(createdAtMs + RETENTION_MS).toISOString();
  const paths = await prepareStore(options.stateRoot);
  const temporaryDirectory = join(paths.temporary, `.capture-${randomUUID()}`);
  await mkdir(temporaryDirectory, { mode: 0o700 });

function workContextBindingView(binding: WorkContextBinding): WorkContextBindingView {
  const { session_id: _sessionId, provenance, ...publicBinding } = binding;
  return {
    ...publicBinding,
    provenance: {
      kind: provenance.kind,
      lifecycle: provenance.lifecycle,
    },
  };
}

